insert into scenes (id, label_ja) values ('scene_phone_desk', 'デスクで固定電話') on conflict (id) do update set label_ja = excluded.label_ja;
insert into audio_clips (id, text, voice, channel) values ('e47e027fd06a1501', '後輩が予定表を見ながら先輩に電話でこう尋ねました。先輩「15日10時、ABC商事さんとみどり産業さんが重なっていますね。みどり産業さんとはもう16日の13時に変更してもらいました。かえで商会さんは17日に延期になったので、16日は空いています。」みどり産業と実際に会うのはいつですか。', 'narrator_f', 'in_person') on conflict (id) do update set text = excluded.text, voice = excluded.voice, channel = excluded.channel;
insert into audio_clips (id, text, voice, channel) values ('26c0ddb3c98e8b61', '見積書を見ながら、同僚がこう言いました。「展示会は10月9日で、できれば早めに届いてほしいんですが、とにかくそれまでに間に合えば大丈夫です。予算は1個500円以内で、今回は250個以上まとめて発注します。さっき確認したら、タンブラーは単価が上がって550円になるそうです。」条件に合う品はどれですか。', 'narrator_f', 'in_person') on conflict (id) do update set text = excluded.text, voice = excluded.voice, channel = excluded.channel;
insert into audio_clips (id, text, voice, channel) values ('fbafa2ed5f38fdc8', '同僚がオンライン会議で予定表を画面に映しながらこう言いました。「4日の第一倉庫、C社さんとB社さんが重なっている件ですが、C社さんの納品はけっきょく延期になって、D社さんと同じ日に入ることになりました。場所は第一倉庫のまま変わりません。」C社の納品はいつになりますか。', 'narrator_f', 'in_person') on conflict (id) do update set text = excluded.text, voice = excluded.voice, channel = excluded.channel;
insert into bundles (id, item_type, level, generator_model, generated_at) values ('shiryou_choudokkai_J3_002', 'shiryou_choudokkai', 'J3', 'claude-sonnet-5', '2026-10-02T04:41:14+00:00') on conflict (id) do update set item_type = excluded.item_type, level = excluded.level, generator_model = excluded.generator_model, generated_at = excluded.generated_at;
insert into items (id, bundle_id, item_type, level, seed_cell_id, setting, relation, function, channel, scene_id, speaker_role, listener_role, topic, stem, correct_index, explanation_ja, explanation_en, vocab_notes, documents, dialogue, narration_clip_id, model_p_correct) values ('81a2e12c4c', 'shiryou_choudokkai_J3_002', 'shiryou_choudokkai', 'J3', 'schedule_sheet+junior_to_senior+find_the_conflict@J3', 'schedule_sheet', 'junior_to_senior', 'find_the_conflict', 'phone', 'scene_phone_desk', null, null, '予定表の重複予約を電話で確認する', '後輩が予定表を見ながら先輩に電話でこう尋ねました。先輩「15日10時、ABC商事さんとみどり産業さんが重なっていますね。みどり産業さんとはもう16日の13時に変更してもらいました。かえで商会さんは17日に延期になったので、16日は空いています。」みどり産業と実際に会うのはいつですか。', 3, '予定表では15日10時にABC商事とみどり産業の予約が重複している。先輩の電話で、みどり産業との約束は16日13時に変更されたと分かる。10月15日10時は変更前の値で誤り、10月14日10時はABC商事の別行を読み違えたもの、10月17日はかえで商会が延期になった日であり、みどり産業とは関係ない。予定表だけでは変更後の時間が分からず、電話だけではどの予約が重複していたか分からない。', 'The sheet shows a double booking; the call reveals which appointment moved and to when, while the other date belongs to a different client''s postponement.', '[{"term": "重複", "reading": "じゅうふく", "meaning": "duplication/overlap"}, {"term": "延期", "reading": "えんき", "meaning": "postponement"}, {"term": "応接室", "reading": "おうせつしつ", "meaning": "reception room"}]', '[{"template": "schedule", "title": "来客対応 予定表", "meta": [{"label": "期間", "value": "10月14日(月)～10月16日(水)"}, {"label": "作成者", "value": "後輩 中村"}], "blocks": [{"type": "table", "columns": ["日付", "時間", "訪問先", "場所"], "rows": [["10/14(月)", "10:00", "ABC商事", "第2応接室"], ["10/14(月)", "14:00", "さくら工業", "本社ロビー（元は第1会議室）"], ["10/15(火)", "10:00", "ABC商事", "第2応接室"], ["10/15(火)", "10:00", "みどり産業", "第1応接室"], ["10/16(水)", "13:00", "かえで商会", "第3応接室"]]}]}]', '[]', 'e47e027fd06a1501', 1.0) on conflict (id) do update set bundle_id = excluded.bundle_id, item_type = excluded.item_type, level = excluded.level, seed_cell_id = excluded.seed_cell_id, setting = excluded.setting, relation = excluded.relation, function = excluded.function, channel = excluded.channel, scene_id = excluded.scene_id, speaker_role = excluded.speaker_role, listener_role = excluded.listener_role, topic = excluded.topic, stem = excluded.stem, correct_index = excluded.correct_index, explanation_ja = excluded.explanation_ja, explanation_en = excluded.explanation_en, vocab_notes = excluded.vocab_notes, documents = excluded.documents, dialogue = excluded.dialogue, narration_clip_id = excluded.narration_clip_id, model_p_correct = excluded.model_p_correct;
insert into items (id, bundle_id, item_type, level, seed_cell_id, setting, relation, function, channel, scene_id, speaker_role, listener_role, topic, stem, correct_index, explanation_ja, explanation_en, vocab_notes, documents, dialogue, narration_clip_id, model_p_correct) values ('1d7ad8bafa', 'shiryou_choudokkai_J3_002', 'shiryou_choudokkai', 'J3', 'quotation+peer_to_peer+choose_the_option@J3', 'quotation', 'peer_to_peer', 'choose_the_option', 'in_person', null, null, null, '展示会ノベルティの発注先を選ぶ', '見積書を見ながら、同僚がこう言いました。「展示会は10月9日で、できれば早めに届いてほしいんですが、とにかくそれまでに間に合えば大丈夫です。予算は1個500円以内で、今回は250個以上まとめて発注します。さっき確認したら、タンブラーは単価が上がって550円になるそうです。」条件に合う品はどれですか。', 0, '条件は「500円以内」「10月9日までに間に合う」「250個以上」の三つ。資料だけを見るとタンブラーも480円で条件を満たすように見えるが、同僚の発言で単価が550円に上がったと分かり除外される。トートバッグとメモ帳は数量が250個に届かず不合格。ノベルティペンだけが単価・数量・納期のすべてを満たす。資料だけでは値上げが分からず、話だけでは各品の単価・数量・納期が分からないため、両方を照らし合わせないと答えが決まらない。', 'Only the pen meets all three spoken conditions once the tumbler''s spoken price hike is applied; the other two fail on quantity alone.', '[{"term": "予算", "reading": "よさん", "meaning": "budget"}, {"term": "まとめて発注", "reading": "まとめてはっちゅう", "meaning": "to place a bulk order"}]', '[{"template": "quote_order", "title": "展示会ノベルティ 見積書", "meta": [{"label": "宛先", "value": "営業部 販促担当者様"}, {"label": "発行者", "value": "ノベルティ工房 営業部 高橋"}, {"label": "発行日", "value": "9月20日"}], "blocks": [{"type": "table", "columns": ["品名", "単価", "数量", "納期"], "rows": [["ノベルティペン", "180円", "300本", "10月5日"], ["タンブラー", "480円", "100個", "10月10日"], ["トートバッグ", "460円", "150枚", "10月8日"], ["メモ帳", "220円", "200冊", "10月3日"]]}]}]', '[]', '26c0ddb3c98e8b61', 1.0) on conflict (id) do update set bundle_id = excluded.bundle_id, item_type = excluded.item_type, level = excluded.level, seed_cell_id = excluded.seed_cell_id, setting = excluded.setting, relation = excluded.relation, function = excluded.function, channel = excluded.channel, scene_id = excluded.scene_id, speaker_role = excluded.speaker_role, listener_role = excluded.listener_role, topic = excluded.topic, stem = excluded.stem, correct_index = excluded.correct_index, explanation_ja = excluded.explanation_ja, explanation_en = excluded.explanation_en, vocab_notes = excluded.vocab_notes, documents = excluded.documents, dialogue = excluded.dialogue, narration_clip_id = excluded.narration_clip_id, model_p_correct = excluded.model_p_correct;
insert into items (id, bundle_id, item_type, level, seed_cell_id, setting, relation, function, channel, scene_id, speaker_role, listener_role, topic, stem, correct_index, explanation_ja, explanation_en, vocab_notes, documents, dialogue, narration_clip_id, model_p_correct) values ('4f749dbe58', 'shiryou_choudokkai_J3_002', 'shiryou_choudokkai', 'J3', 'video_shared_doc+peer_to_peer+find_the_date@J3', 'video_shared_doc', 'peer_to_peer', 'find_the_date', 'video', null, null, null, '倉庫予約の重なりと延期連絡', '同僚がオンライン会議で予定表を画面に映しながらこう言いました。「4日の第一倉庫、C社さんとB社さんが重なっている件ですが、C社さんの納品はけっきょく延期になって、D社さんと同じ日に入ることになりました。場所は第一倉庫のまま変わりません。」C社の納品はいつになりますか。', 2, '予定表では10月4日に第一倉庫でB社とC社の予定が重なっており、C社は「仮」とされている。話し手はこの重なりを解消するため、C社の納品をD社と同じ日、つまり10月9日に延期すると伝えている。10月4日は延期前の資料の値のままで誤り。9月30日はC社の別の作業（検品）の完了日であり、これから行う納品とは別物。10月2日はA社の行を誤って読んだもの。資料だけでは重なりの解消先が分からず、音声だけではD社の日付が10月9日だと分からない。', 'The chart shows a double booking on the 4th; the colleague resolves it by moving C''s delivery to the same date as D''s slot, October 9.', '[{"term": "納品立会い", "reading": "のうひんたちあい", "meaning": "attending a delivery to confirm receipt"}, {"term": "仮予約", "reading": "かりよやく", "meaning": "provisional reservation"}]', '[{"template": "schedule", "title": "10月 納品立会い予定表", "meta": [{"label": "期間", "value": "9月30日（土）〜10月9日（月）"}, {"label": "作成者", "value": "総務部 中村"}], "blocks": [{"type": "table", "columns": ["日付", "内容", "場所", "担当"], "rows": [["9月30日（土）", "C社 検品（完了）", "第一倉庫", "高橋"], ["10月2日（月）", "A社 納品立会い", "本社倉庫", "佐藤"], ["10月4日（水）", "B社 納品立会い", "第一倉庫", "鈴木"], ["10月4日（水）", "C社 納品立会い（仮）", "第一倉庫", "高橋"], ["10月9日（月）", "D社 納品立会い", "第二倉庫", "佐藤"]]}]}]', '[]', 'fbafa2ed5f38fdc8', 1.0) on conflict (id) do update set bundle_id = excluded.bundle_id, item_type = excluded.item_type, level = excluded.level, seed_cell_id = excluded.seed_cell_id, setting = excluded.setting, relation = excluded.relation, function = excluded.function, channel = excluded.channel, scene_id = excluded.scene_id, speaker_role = excluded.speaker_role, listener_role = excluded.listener_role, topic = excluded.topic, stem = excluded.stem, correct_index = excluded.correct_index, explanation_ja = excluded.explanation_ja, explanation_en = excluded.explanation_en, vocab_notes = excluded.vocab_notes, documents = excluded.documents, dialogue = excluded.dialogue, narration_clip_id = excluded.narration_clip_id, model_p_correct = excluded.model_p_correct;
